mapper.select:
SELECT id, cart_id, product_id, sku_id, product_name, product_price, quantity
FROM cart_item
WHERE sku_id = #{skuId}
  AND cart_id = #{cartId}
LIMIT 1

mapper.update:
UPDATE cart_item
SET quantity = #{quantity},
    product_name = #{productName},
    product_price = #{productPrice}
WHERE id = #{id}
  AND cart_id = #{cartId}
  AND sku_id = #{skuId}

